messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
    </style>
</head>
<body>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Sky Blue

        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const sunLight = new THREE.DirectionalLight(0xffffff, 0.8);
        sunLight.position.set(10, 20, 10);
        scene.add(sunLight);

        // --- Environment ---
        // Ground/Track
        const groundGeo = new THREE.PlaneGeometry(20, 200);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        scene.add(ground);

        // Finish Line
        const finishLineGeo = new THREE.PlaneGeometry(20, 2);
        const finishLineMat = new THREE.MeshStandardMaterial({ color: 0xffffff });
        const finishLine = new THREE.Mesh(finishLineGeo, finishLineMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.y = 0.01;
        finishLine.position.z = -80;
        scene.add(finishLine);

        // Checkered pattern on finish line (simple stripes)
        for(let i = -10; i <= 10; i+=2) {
            const stripeGeo = new THREE.PlaneGeometry(2, 2);
            const stripeMat = new THREE.MeshStandardMaterial({ color: 0x000000 });
            const stripe = new THREE.Mesh(stripeGeo, stripeMat);
            stripe.rotation.x = -Math.PI / 2;
            stripe.position.set(i, 0.02, -80);
            scene.add(stripe);
        }

        // --- Car Factory ---
        function createCar(color) {
            const group = new THREE.Group();

            // Body
            const body = new THREE.Mesh(
                new THREE.BoxGeometry(2, 1, 4),
                new THREE.MeshStandardMaterial({ color: color })
            );
            body.position.y = 0.7;
            group.add(body);

            // Cabin
            const cabin = new THREE.Mesh(
                new THREE.BoxGeometry(1.5, 0.8, 1.5),
                new THREE.MeshStandardMaterial({ color: 0xdddddd })
            );
            cabin.position.set(0, 1.5, -0.2);
            group.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.4, 0.4, 0.5, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x222222 });
            const wheelPos = [
                [-1.1, 0.4, 1.2], [1.1, 0.4, 1.2],
                [-1.1, 0.4, -1.2], [1.1, 0.4, -1.2]
            ];
            wheelPos.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(...pos);
                group.add(wheel);
            });

            return group;
        }

        const redCar = createCar(0xff0000);
        const blueCar = createCar(0x0000ff);

        redCar.position.set(-3, 0, 0);
        blueCar.position.set(3, 0, 0);

        scene.add(redCar);
        scene.add(blueCar);

        // --- Animation Logic ---
        let startTime = Date.now();
        const raceDuration = 6000; // 6 seconds per loop
        const finishZ = -80;

        function animate() {
            requestAnimationFrame(animate);

            const elapsed = (Date.now() - startTime) % raceDuration;
            const progress = elapsed / raceDuration; // 0 to 1

            // Blue Car: Constant speed, then slows slightly
            // Starts fast, ends at finish line around the end of duration
            const blueZ = progress * finishZ;

            // Red Car: Starts slower, then accelerates mid-way
            // Use a power function to simulate acceleration
            // At progress 0.5, red should be catching up. At 0.8, it should lead.
            const redZ = Math.pow(progress, 1.5) * (finishZ - 5) + (progress * 5);

            // Correcting Red's curve to ensure it wins:
            // We want Red to cross finishZ before Blue does.
            // Let's use a simpler interpolation:
            const redSpeedFactor = progress < 0.4 ? 0.8 : (progress < 0.7 ? 1.2 : 1.5);
            // To make it smooth, we'll use a quadratic:
            const smoothRedZ = (progress * progress * 1.2 + progress * 0.8) * (finishZ / 1.8);

            // Final Position Assignment
            blueCar.position.z = progress * finishZ;
            // Red starts slow (progress), then accelerates (progress^2)
            redCar.position.z = (0.6 * progress + 1.4 * Math.pow(progress, 2)) * finishZ;

            // Camera follow
            const centerZ = (redCar.position.z + blueCar.position.z) / 2;
            camera.position.set(0, 8, centerZ + 15);
            camera.lookAt(0, 0, centerZ - 10);

            renderer.render(scene, camera);
        }

        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```
